{"files": [{"content": "{
  "main_characters": [
    {
      "name": "林微",
      "role": "protagonist",
      "identity": "高三学生/透明人",
      "traits": ["孤僻", "坚韧", "敏感", "决绝"],
      "overt_motivation": "躲避校园霸凌，寻找安全的角落",
      "covert_motivation": "潜意识里寻找失踪三年的江澈，渴望被理解",
      "secret_fear": "被世界彻底遗忘，像尘埃一样消失",
      "misperception_of_other": "以为江澈当年是不辞而别",
      "hidden_connection": "她是唯一能听见江澈声音的人（虽然之前以为是幻听）"
    },
    {
      "name": "江澈",
      "role": "deuteragonist",
      "identity": "失踪学霸/透明层居民",
      "traits": ["温柔", "执着", "孤独", "隐忍"],
      "overt_motivation": "守护林微，不让她受到伤害",
      "covert_motivation": "渴望再次被林微看见，却又害怕她因此陷入危险",
      "secret_fear": "林微为了陪他而永远留在透明层",
      "misperception_of_other": "以为林微已经忘记了自己",
      "hidden_connection": "三年来一直生活在林微的身边，是她的'背后灵'"
    }
  ],
  "supporting_characters": [
    {
      "name": "张婷",
      "function": "阻碍",
      "identity": "霸凌者/同班同学",
      "description": "林微痛苦的来源，促使林微触发规则的推手。在透明层视角下，她的恶意呈现为黑色的雾气。"
    },
    {
      "name": "老陈",
      "function": "反转点",
      "identity": "学校门卫",
      "description": "似乎知道学校的隐形规则，是规则的守门人，给林微提供了模糊的警示。"
    }
  ],
  "relationship_dynamics": "双向暗恋的极致形态。江澈是林微唯一的守护者，林微是江澈唯一的观测者。两人在24小时的倒计时中，从'看不见'到'看得见'，最后回归'遗忘'，完成了一次绝望而唯美的闭环。"
}", "path": "characters.json"}, {"content": "{
  "act_one": {
    "description": "第一幕：透明的边界（约5000字）。林微为了躲避霸凌触发规则，进入透明层，与失踪的江澈重逢。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "死角的三分钟",
        "core_event": "林微被霸凌者堵截，逃入监控死角，故意停留超过3分钟触发传说中的规则。",
        "emotional_tone": "压抑、紧张、绝望",
        "key_scenes": ["厕所的冷水", "监控死角的红点熄灭", "世界突然寂静"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "看不见的拥抱",
        "core_event": "林微发现自己变成了透明人，回到教室看到江澈正坐在她的座位旁对着空气说话。",
        "emotional_tone": "震惊、迷茫、酸涩",
        "key_scenes": ["穿过同学的身体", "江澈的独白", "林微试图触碰江澈"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "重逢的代价",
        "core_event": "两人正式相认。江澈告知林微规则的真相：24小时后她会回归，但会遗忘这一切。",
        "emotional_tone": "激动、悲伤、无力",
        "key_scenes": ["指尖的触碰", "江澈解释透明层", "倒计时开始"]
      }
    ],
    "turning_point": "林微决定利用这最后的24小时，和江澈完成一场没有未来的约会。"
  },
  "act_two": {
    "description": "第二幕：倒计时的温存（约15000字）。两人在透明层游荡，回顾过去，同时面临规则的侵蚀。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "第23小时：逃离",
        "core_event": "两人逃离学校，在喧嚣的城市中享受只有彼此的宁静。",
        "emotional_tone": "自由、浪漫、微甜",
        "key_scenes": ["穿过拥挤的十字路口", "无人便利店的'偷窃'", "公交车后排的依偎"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第18小时：旧时光",
        "core_event": "回到两人曾经的秘密基地（旧书店），回忆起三年前未宣之于口的暗恋。",
        "emotional_tone": "怀旧、温暖、遗憾",
        "key_scenes": ["书页中的干花", "三年前的借书卡", "江澈视角的暗恋真相"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "第12小时：透明的裂痕",
        "core_event": "林微的身体开始出现不稳定迹象（噪点），江澈隐瞒了自己即将消散的秘密。",
        "emotional_tone": "不安、隐忍、悬疑",
        "key_scenes": ["林微手指的闪烁", "江澈痛苦的表情", "透明层边缘的黑色雾气"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "第8小时：未寄出的信",
        "core_event": "林微发现了江澈三年来在起雾玻璃上写下的无数封'信'，每一封都是给她的。",
        "emotional_tone": "感动、虐心、泪目",
        "key_scenes": ["雨天的窗户", "重叠的字迹", "林微的崩溃"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "第4小时：规则的恶意",
        "core_event": "霸凌者张婷似乎感应到了透明层的存在，恶意具象化。江澈为保护林微动用力量，加速了自己的消亡。",
        "emotional_tone": "紧张、冲突、牺牲",
        "key_scenes": ["张婷的恶意凝视", "江澈挡在林微身前", "江澈身体变得半透明"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "第2小时：最后的愿望",
        "core_event": "林微试图用各种方式记录下这段记忆，但所有载体都在瞬间复原。",
        "emotional_tone": "绝望、挣扎、不舍",
        "key_scenes": ["手机录音自动删除", "写在手臂上的字迹消失", "林微哭着背诵江澈的名字"]
      }
    ],
    "turning_point": "江澈告诉林微，如果她不忘记，就会永远留在透明层，变成和他一样的'鬼魂'。"
  },
  "act_three": {
    "description": "第三幕：遗忘的潮汐（约10000字）。时间终结，林微回归现实，遗忘一切，达成BE美学。",
    "key_chapters": [
      {
        "chapter_number": 10,
        "chapter_title": "第10分钟：告别",
        "core_event": "两人回到最初的监控死角。江澈变得极度虚弱，最后一次拥抱林微。",
        "emotional_tone": "凄美、宁静、极致悲伤",
        "key_scenes": ["最后的拥抱", "江澈的嘱托", "倒计时归零"]
      },
      {
        "chapter_number": 11,
        "chapter_title": "第0秒：重启",
        "core_event": "林微在现实中醒来，记忆被强行抹除，只剩下莫名的心痛。",
        "emotional_tone": "空虚、恍惚、怅然",
        "key_scenes": ["喧闹的校园", "林微摸着心脏的位置", "完全想不起发生了什么"]
      },
      {
        "chapter_number": 12,
        "chapter_title": "尾声：风的声音",
        "core_event": "林微正常生活，经过死角时感到风吹过耳边。江澈在透明层看着她，微笑着说再见。",
        "emotional_tone": "余韵悠长、BE美学",
        "key_scenes": ["林微的回眸", "看不见的江澈", "风中的低语"]
      }
    ]
  }
}", "path": "outline.json"}]}

