              },
              "core_event": {
                "type": "string",
                "description": "本章核心事件（1-2句话）"
              },
              "emotional_tone": {
                "type": "string",
                "description": "本章情感基调"
              },
              "key_scenes": {
                "type": "array",
                "description": "本章关键场景列表",
